-- Service: billing  (global, one per region)
-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, billing.sql, billing.later.sql, _epilogue.sql
-- =============================================================================
-- 12. BILLING and metering  (FR-1110 Must P1, FR-1005, AC-1110)
-- =============================================================================
CREATE TABLE plans (
  key text PRIMARY KEY, name text NOT NULL,
  seat_limit integer, storage_bytes bigint, automation_runs_month integer, api_calls_month bigint,
  features jsonb NOT NULL DEFAULT '{}'
);

CREATE TABLE subscriptions (
  id uuid PRIMARY KEY,
  tenant_id uuid /* id -> routing.tenants */, workspace_id uuid /* id -> access.workspaces */,
  plan_key text NOT NULL REFERENCES plans(key),
  seats integer NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('trial','active','past_due','cancelled')),
  period_start date NOT NULL, period_end date NOT NULL,
  external_ref text,                                        -- payment provider customer id
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  CHECK (tenant_id IS NOT NULL OR workspace_id IS NOT NULL)
);

CREATE TABLE usage_counters (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  period date NOT NULL,                                     -- first day of month
  metric text NOT NULL CHECK (metric IN ('seats','storage_bytes','automation_runs','api_calls','ai_calls')),
  value bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (workspace_id, period, metric)
);

CREATE TABLE invoices (
  id uuid PRIMARY KEY,
  subscription_id uuid NOT NULL REFERENCES subscriptions(id),
  period_start date NOT NULL, period_end date NOT NULL,
  amount_cents bigint NOT NULL, currency char(3) NOT NULL,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','paid','void')),
  external_ref text, issued_at timestamptz NOT NULL DEFAULT now()
);
